/*
 * 09 — BETTER PACKAGING / RESOURCE-SMART DESIGN
 * Pure Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: open and inspect / align inserts / close and seal.
 * Rigid 2D flap rotation, fixed hinges, fixed-size inserts, exact 25-second loop.
 * Static background. No assets, fonts, perspective, blur, shadows, or glow.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * Set encoding bitrate in the host video exporter; Canvas renders pixels only.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const scale = minSide / 1000;
  const ink = '#35554d';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const eased = smooth(sceneProgress);
  const opening = currentScene === 0 ? eased : currentScene === 1 ? 1 : 1 - eased;
  const reveal = currentScene === 0 ? eased : currentScene === 1 ? 1 - eased : 0;
  const flapAngle = 0.32 * opening;

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function flap(side) {
    ctx.save();
    ctx.translate(side * 270, -80);
    ctx.rotate(side * flapAngle);
    ctx.scale(-side, 1);
    const paper = ctx.createLinearGradient(0, -132, 262, 0);
    paper.addColorStop(0, '#ddc5a0');
    paper.addColorStop(1, '#cbb087');
    box(0, -132, 262, 132, 8, paper, ink, 5.5);
    line(16, -18, 246, -18, '#9b9c77', 1.8);
    line(16, -114, 246, -114, '#b2a581', 1.5);
    for (let n = 0; n < 7; n++) {
      const x = 24 + n * 33;
      const y = -83 + (n % 2) * 13;
      line(x, y, x + 9, y + 1.4, '#b7a883', 1.1);
      line(x + 3, y + 19, x + 12, y + 17.8, '#b7a883', 1.1);
    }
    ctx.restore();
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // The warm sand / terracotta background and corner marks never animate.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#dfd4bf');
  background.addColorStop(0.5, '#c6aa90');
  background.addColorStop(1, '#a77f6e');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);
  for (const side of [-1, 1]) {
    for (const y of [-376, 376]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 622, y + sy * 22);
      ctx.lineTo(side * 622, y);
      ctx.lineTo(side * 600, y);
      ctx.strokeStyle = 'rgba(53,85,77,0.20)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }

  // One uniform scale; the box and hinge anchors stay fixed throughout.
  ctx.scale(1.12, 1.12);
  ctx.translate(0, -30);
  flap(-1);
  flap(1);

  const carton = ctx.createLinearGradient(-298, -80, 298, 360);
  carton.addColorStop(0, '#dfc5a0');
  carton.addColorStop(1, '#c9a77c');
  box(-298, -80, 596, 440, 17, carton, ink, 6);

  // Front-elevation cutaway: protective inserts remain fully inside its frame.
  const cutaway = ctx.createLinearGradient(-250, -42, 250, 240);
  cutaway.addColorStop(0, '#e8dcc0');
  cutaway.addColorStop(1, '#d6c6a5');
  box(-250, -42, 500, 282, 12, cutaway, '#82957a', 3.2);
  line(-219, 215, 219, 215, '#a5a27c', 1.8);
  const home = [-147, -49, 49, 147];
  const travel = [-18, -6, 6, 18];
  for (let n = 0; n < 4; n++) {
    // Alignment markers are stationary; only the intact inserts translate.
    box(home[n] - 37, 197, 74, 9, 3, '#b4b295', '#8b9a7a', 1.3);
    const x = home[n] + travel[n] * reveal;
    const insert = ctx.createLinearGradient(x - 35, -12, x + 35, 178);
    insert.addColorStop(0, '#dec59c');
    insert.addColorStop(1, '#c1ad83');
    box(x - 35, -12, 70, 190, 8, insert, '#577365', 3.2);
    ctx.beginPath();
    for (let j = 0; j < 9; j++) {
      const xx = x + (j % 2 === 0 ? -21 : 21);
      const yy = 8 + j * 18;
      if (j === 0) ctx.moveTo(xx, yy);
      else ctx.lineTo(xx, yy);
    }
    ctx.strokeStyle = '#8b9874';
    ctx.lineWidth = 2.1;
    ctx.stroke();
    line(x - 16, 164, x + 16, 164, '#a2a17a', 1.5);
  }

  // Printed paper fibers and fold seams belong to the carton, not the background.
  for (const side of [-1, 1]) {
    line(side * 276, -57, side * 276, 335, '#a19b73', 2.1);
    for (let row = 0; row < 8; row++) {
      const x = side * 264;
      const y = -40 + row * 48;
      line(x - 5, y - 0.7, x + 5, y + 0.7, '#af9e78', 1.1);
    }
  }

  // Fixed hinge caps conceal the intentional mechanical attachment points.
  for (const x of [-270, 270]) {
    circle(x, -80, 7, '#a7b295', ink, 2.3);
    circle(x, -80, 2.2, '#d3c59d', null, 0);
  }

  // An original geometric seal; no brand, certification mark, or outside asset.
  ctx.beginPath();
  for (let j = 0; j < 6; j++) {
    const a = -Math.PI / 2 + j * TAU / 6;
    const x = 31 * Math.cos(a);
    const y = 299 + 31 * Math.sin(a);
    if (j === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = '#86a28c';
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 2.7;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-9, 300);
  ctx.lineTo(-2, 307);
  ctx.lineTo(11, 291);
  ctx.strokeStyle = '#e4d6b5';
  ctx.lineWidth = 3.6;
  ctx.stroke();
  for (let n = 0; n < 3; n++) {
    const a = phase * TAU * 2 + n * TAU / 3;
    circle(Math.cos(a) * 21.5, 299 + Math.sin(a) * 21.5,
           1.9, '#d8ccab', null, 0);
  }

  ctx.restore();
  ctx.beginPath();
}

/*
 * 10 — LIGHT EFFICIENTLY / INTELLIGENT LED LIGHTING
 * Pure Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: activate LEDs / regulate input / balanced operation.
 * Fixed bulb, diffuser, circuitry, and screw-base geometry; exact 25-second loop.
 * Static background. LED activity is matte color only: no glow or light beams.
 * No assets, fonts, blur, shadows, perspective, or camera movement.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * Set encoding bitrate in the host video exporter; Canvas renders pixels only.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#303c56';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const activation = emphasis[0];
  const regulation = emphasis[1];
  const balanced = emphasis[2];

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function bulbPath() {
    ctx.beginPath();
    ctx.moveTo(-109, 190);
    ctx.lineTo(-109, 177);
    ctx.bezierCurveTo(-109, 125, -151, 85, -188, 39);
    ctx.bezierCurveTo(-236, -21, -255, -75, -255, -143);
    ctx.bezierCurveTo(-255, -277, -148, -365, 0, -365);
    ctx.bezierCurveTo(148, -365, 255, -277, 255, -143);
    ctx.bezierCurveTo(255, -75, 236, -21, 188, 39);
    ctx.bezierCurveTo(151, 85, 109, 125, 109, 177);
    ctx.lineTo(109, 190);
    ctx.closePath();
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // Fixed indigo / dusty-violet field: no halo, rays, bloom, or animated layers.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#293754');
  background.addColorStop(0.5, '#485571');
  background.addColorStop(1, '#747b98');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);
  for (const side of [-1, 1]) {
    for (const y of [-376, 376]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 622, y + sy * 22);
      ctx.lineTo(side * 622, y);
      ctx.lineTo(side * 600, y);
      ctx.strokeStyle = 'rgba(215,225,211,0.21)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }
  ctx.scale(1.04, 1.04);

  bulbPath();
  const enclosure = ctx.createLinearGradient(-255, -365, 255, 190);
  enclosure.addColorStop(0, '#e3e7dd');
  enclosure.addColorStop(1, '#c3d2cc');
  ctx.fillStyle = enclosure;
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 6;
  ctx.stroke();

  // A filled, outlined diffuser component inside the bulb; never an outer aura.
  const diffuser = ctx.createLinearGradient(-183, -330, 183, 36);
  diffuser.addColorStop(0, '#e6e8d9');
  diffuser.addColorStop(1, '#cbd8cb');
  circle(0, -147, 183, diffuser, '#859f9e', 2.9);

  // Circuit traces occupy explicit corridors between the LED modules.
  line(0, 185, 0, -54, '#587383', 8);
  line(0, 185, 0, -54, '#91afa8', 5.6);
  line(-105, -54, 105, -54, '#71968e', 3.2);
  for (const x of [-80, 0, 80]) {
    line(x, -54, x, -93, '#71968e', 3.2);
    line(x, -141, x, -171, '#71968e', 3.2);
  }

  // Alternating packets fade during regulation, creating wider input spacing
  // without changing the physical speed, packet radius, or trajectory.
  for (let n = 0; n < 6; n++) {
    const u = (phase * 5 + n / 6) % 1;
    const strength = 0.85 - (n % 2 === 1 ? 0.82 * regulation : 0);
    ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * strength;
    circle(0, 184 - u * 237, 2, '#ded0a0', null, 0);
  }
  ctx.globalAlpha = 1;

  // Six intact LED modules. Only their matte surface colors indicate activity.
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const x = -80 + col * 80;
      const y = -195 + row * 78;
      const wave = 0.5 + 0.5 * Math.cos(angle * 2 - col * 0.76 - row * 1.02);
      const distribution = 0.5 + 0.5 * Math.sin(angle * 3 - col * 0.5 - row * 0.8);
      const active = clamp(0.42 + activation * 0.38 * wave
                         + regulation * (0.30 + Math.sin(angle * 2) * 0.02)
                         + balanced * (0.23 + 0.10 * distribution));
      const module = ctx.createLinearGradient(x - 29, y - 24, x + 29, y + 24);
      module.addColorStop(0, mix([197, 207, 178], [231, 225, 187], active));
      module.addColorStop(1, mix([169, 190, 168], [205, 211, 175], active));
      box(x - 29, y - 24, 58, 48, 7, module, '#637e7c', 2.8);
      box(x - 9, y - 8, 18, 16, 3,
        mix([155, 168, 142], [233, 216, 162], active), '#738773', 1.4);
      for (const yy of [y - 17, y + 17]) {
        line(x - 10, yy, x + 10, yy, '#9caa87', 1.3);
      }
    }
  }
  // Explicit port masks the intentional trace crossing of the diffuser rim.
  box(-12, 29, 24, 16, 4, '#b0c6b4', '#658b8a', 2);

  // Integrated power regulator. The small arc is inside its component housing.
  for (const y of [96, 118, 140]) {
    for (const side of [-1, 1]) line(side * 55, y, side * 64, y, '#72978f', 2.6);
  }
  box(-55, 82, 110, 73, 10, '#a5bfb2', ink, 3.3);
  for (const x of [-29, 0, 29]) line(x - 5, 94, x + 5, 94, '#7b9e91', 1.7);
  const load = 0.72 * activation + 0.43 * regulation + 0.54 * balanced
              + 0.025 * Math.sin(angle * 2) * (activation + balanced * 0.4);
  ctx.beginPath();
  ctx.arc(0, 130, 25, Math.PI, TAU);
  ctx.strokeStyle = '#6b8c89';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, 130, 25, Math.PI, Math.PI + Math.PI * load);
  ctx.strokeStyle = '#d1bb88';
  ctx.lineWidth = 3.2;
  ctx.stroke();
  const needle = Math.PI + Math.PI * load;
  line(0, 130, Math.cos(needle) * 19, 130 + Math.sin(needle) * 19, ink, 2.5);
  circle(0, 130, 3.4, ink, null, 0);

  // Flat front-elevation screw base and terminal; no extrusion or reflected light.
  box(-43, 327, 86, 35, 11, '#a3b3b5', ink, 4.7);
  const base = ctx.createLinearGradient(-106, 209, 106, 330);
  base.addColorStop(0, '#b8c4cb');
  base.addColorStop(1, '#8da3b2');
  box(-106, 209, 212, 121, 12, base, ink, 5);
  for (let n = 0; n < 4; n++) {
    box(-98, 222 + n * 24, 196, 12, 5,
        n % 2 === 0 ? '#a7b9c0' : '#9bafb9', '#627b8e', 1.8);
  }
  box(-121, 177, 242, 37, 9, '#b0c3c4', ink, 4.6);
  line(-99, 195, 99, 195, '#8da9aa', 1.7);

  ctx.restore();
  ctx.beginPath();
}

/*
 * 07 — CHARGE FORWARD / SUSTAINABLE ELECTRIC MOBILITY
 * Pure Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: connection / energy transfer / steady charging.
 * Fixed connector and cable geometry; exact 25-second visual loop.
 * Static background. No assets, text, blur, shadows, glow, or camera motion.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * The host video exporter must set the bitrate; Canvas only renders pixels.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#193f57';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const connection = emphasis[0];
  const transfer = emphasis[1];
  const steady = emphasis[2];

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function cablePath() {
    ctx.beginPath();
    ctx.moveTo(-430, -55);
    ctx.lineTo(-430, 290);
    ctx.arc(-350, 290, 80, Math.PI, Math.PI / 2, true);
    ctx.lineTo(10, 370);
    ctx.arc(10, 290, 80, Math.PI / 2, 0, true);
    ctx.lineTo(90, 244);
  }

  // Exact arc-length sampling gives every current packet the same linear speed.
  function cablePoint(u) {
    const arcLength = 40 * Math.PI;
    const total = 345 + arcLength + 360 + arcLength + 46;
    let d = u * total;
    if (d <= 345) return [-430, -55 + d];
    if ((d -= 345) <= arcLength) {
      const a = Math.PI - d / 80;
      return [-350 + 80 * Math.cos(a), 290 + 80 * Math.sin(a)];
    }
    if ((d -= arcLength) <= 360) return [-350 + d, 370];
    if ((d -= 360) <= arcLength) {
      const a = Math.PI / 2 - d / 80;
      return [10 + 80 * Math.cos(a), 290 + 80 * Math.sin(a)];
    }
    d -= arcLength;
    return [90, 290 - d];
  }

  function gripPath() {
    ctx.beginPath();
    ctx.moveTo(9, -126);
    ctx.lineTo(171, -126);
    ctx.quadraticCurveTo(192, -126, 190, -104);
    ctx.lineTo(169, 165);
    ctx.quadraticCurveTo(167, 195, 139, 199);
    ctx.lineTo(41, 199);
    ctx.quadraticCurveTo(13, 195, 11, 165);
    ctx.lineTo(-10, -104);
    ctx.quadraticCurveTo(-12, -126, 9, -126);
    ctx.closePath();
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
