  background.addColorStop(0, '#194b74');
  background.addColorStop(0.5, '#366f89');
  background.addColorStop(1, '#79a6aa');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);
  for (const side of [-1, 1]) {
    for (const y of [-376, 376]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 622, y + sy * 22);
      ctx.lineTo(side * 622, y);
      ctx.lineTo(side * 600, y);
      ctx.strokeStyle = 'rgba(210,229,218,0.22)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
