  // Centers the complete connector-and-cable silhouette, not just the grip.
  ctx.translate(112, 0);
  cablePath();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 22;
  ctx.stroke();
  cablePath();
  const cable = ctx.createLinearGradient(-430, -55, 90, 370);
  cable.addColorStop(0, '#a4c6be');
  cable.addColorStop(1, '#75aaa8');
  ctx.strokeStyle = cable;
  ctx.lineWidth = 14;
  ctx.stroke();
  cablePath();
  ctx.strokeStyle = '#6f9f9f';
  ctx.lineWidth = 2;
  ctx.stroke();
  for (let n = 0; n < 6; n++) {
    const u = (phase * 3 + n / 6) % 1;
    const p = cablePoint(u);
    ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2)
                    * (0.55 + 0.38 * transfer + 0.10 * steady);
    circle(p[0], p[1], 3.4, '#e6c78e', null, 0);
