  ctx.globalAlpha = 1;

  box(-454, -128, 48, 76, 11, '#c6d9cd', ink, 4.2);
  for (let n = 0; n < 3; n++) {
    line(-441, -108 + n * 17, -419, -108 + n * 17, '#709b9b', 2.5);
  }

