  for (const y of [218, 232, 246]) line(64, y, 116, y, '#5d9298', 2.2);
  gripPath();
  const grip = ctx.createLinearGradient(-10, -126, 190, 199);
  grip.addColorStop(0, '#e1e9dd');
  grip.addColorStop(1, '#bdd5c9');
  ctx.fillStyle = grip;
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 5.5;
  ctx.stroke();
  box(26, -72, 128, 209, 18, '#8db6b2', '#507d88', 3);

  // Matte inlaid power symbol; its geometry never changes.
  ctx.beginPath();
  ctx.moveTo(91, -42);
  ctx.lineTo(65, -3);
  ctx.lineTo(86, -3);
  ctx.lineTo(77, 31);
  ctx.lineTo(115, -14);
  ctx.lineTo(92, -14);
  ctx.lineTo(104, -42);
  ctx.closePath();
  ctx.fillStyle = '#ddc799';
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 3;
  ctx.stroke();

  const level = 0.42 * connection + 0.78 * transfer + 0.66 * steady
              + Math.sin(angle * 2) * (0.035 * connection + 0.025 * transfer + 0.012 * steady);
  for (let n = 0; n < 5; n++) {
    const active = smooth((level - (n + 0.25) / 5) * 5);
    box(43 + n * 20, 85, 13, 24, 3,
      mix([124, 164, 158], [41, 103, 122], active), '#547f85', 1.3);
  }
  for (const y of [154, 165, 176]) line(44, y, 136, y, '#89aba0', 2.2);

  // The front-facing head intentionally overlaps its fixed grip collar.
  const head = ctx.createLinearGradient(-38, -350, 218, -102);
  head.addColorStop(0, '#e4ebdf');
  head.addColorStop(1, '#c0d8ce');
  box(-38, -350, 256, 248, 35, head, ink, 5.5);
  circle(90, -245, 88, '#547f90', ink, 5);
  circle(90, -245, 72, '#2f6077', '#8eb5b6', 2.3);

  const pins = [[65,-278,12],[115,-278,12],
                [48,-244,12],[90,-244,12],[132,-244,12],
                [75,-209,10],[105,-209,10]];
  for (let n = 0; n < pins.length; n++) {
    const [x,y,r] = pins[n];
    const wave = Math.pow(0.5 + 0.5 * Math.cos(angle * 3 - n * 0.62), 2);
    const active = clamp(0.16 + 0.38 * connection * wave + 0.58 * transfer * wave
                       + 0.24 * steady * (0.6 + wave * 0.4));
    circle(x, y, r, '#a9c5bb', ink, 2.2);
    circle(x, y, r * 0.53,
      mix([49, 97, 111], [192, 175, 129], active), ink, 1.1);
  }
  for (const [x,y] of [[11,-245],[169,-245],[90,-324]]) {
    circle(x,y,3.3,'#b8d0c6',ink,1.3);
  }
  box(17, -142, 146, 18, 5, '#9dbeb5', '#618b90', 1.8);
  for (let n = 0; n < 7; n++) {
    line(34 + n * 19, -137, 34 + n * 19, -129, '#567f86', 1.7);
  }

  ctx.restore();
  ctx.beginPath();
}

/*
 * 08 — CARBON CAPTURE / CLEANER INDUSTRIAL SYSTEMS
 * Pure Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: intake / adsorption / clean-air output.
 * Exact 25-second loop; fixed front elevation and static background.
 * No assets, font dependencies, blur, shadows, glow, or camera movement.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * The host video exporter must set the bitrate; Canvas only renders pixels.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#253c4d';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const intake = emphasis[0];
  const adsorption = emphasis[1];
  const output = emphasis[2];
  const lanes = [-110, -38, 34, 106];
  const filterCenters = [-176, 0, 176];
  const targets = [0, 1, 2, 0];

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  // Integral of the quintic easing function, used to ease velocity rather than
  // scale the particles. All four lanes share a 160-unit/second cruise speed.
  function velocityIntegral(q) {
    return q * q * q * q * (q * q - 3 * q + 2.5);
  }

  function travel(distance, age) {
    const speed = 160;
    const ramp = 0.45;
    const cruise = distance / speed - ramp;
    const arrival = cruise + 2 * ramp;
    let position;
    if (age <= ramp) {
      position = speed * ramp * velocityIntegral(clamp(age / ramp));
    } else if (age <= ramp + cruise) {
      position = speed * ramp * 0.5 + speed * (age - ramp);
    } else if (age < arrival) {
      const q = clamp((age - ramp - cruise) / ramp);
      position = speed * ramp * 0.5 + speed * cruise
               + speed * ramp * (q - velocityIntegral(q));
    } else position = distance;
    return { position, arrival };
  }

  const events = [];
  for (let row = 0; row < 4; row++) {
    const center = filterCenters[targets[row]];
    const goal = center - 50;
    const age = ((phase * 4 + row * 0.19) % 1) * (duration / 4);
    const motion = travel(goal + 493, age);
    const envelope = smooth(age / 0.22)
                   * (1 - smooth((age - motion.arrival - 0.65) / 0.7));
    const captured = smooth((age - motion.arrival + 0.24) / 0.24)
                   * (1 - smooth((age - motion.arrival - 0.65) / 0.7));
    events.push({ x: -493 + motion.position, y: lanes[row], center, goal,
                  opacity: envelope * (0.52 + 0.40 * intake + 0.28 * adsorption),
                  captured });
  }

  function particle(event) {
    ctx.globalAlpha = event.opacity;
    circle(event.x, event.y, 6, null, '#dfbd90', 2);
    ctx.globalAlpha = 1;
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // Entire background is fixed; every moving mark belongs to a physical channel.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#253443');
  background.addColorStop(0.5, '#3b5361');
  background.addColorStop(1, '#69818a');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);
  for (const side of [-1, 1]) {
    for (const y of [-376, 376]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 660, y + sy * 22);
      ctx.lineTo(side * 660, y);
      ctx.lineTo(side * 638, y);
      ctx.strokeStyle = 'rgba(203,219,210,0.22)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }

  // Attached intake and outlet ducts sit behind the main housing.
  for (const x of [-522, 316]) {
    box(x, -142, 206, 284, 21, '#8ea8ae', ink, 4.5);
    box(x + 14, -126, 178, 252, 11, '#365362', '#64818b', 2);
  }
  const housing = ctx.createLinearGradient(-332, -320, 332, 330);
  housing.addColorStop(0, '#d0dcda');
  housing.addColorStop(1, '#a1bac0');
  box(-332, -320, 664, 650, 27, housing, ink, 5.7);
  box(-286, -188, 572, 366, 17, '#344f60', ink, 3.7);

  for (const y of lanes) {
    box(-338, y - 13, 58, 26, 5, '#365362', '#6c8a92', 2);
    box(280, y - 13, 58, 26, 5, '#365362', '#6c8a92', 2);
    line(-500, y, 500, y, '#64828d', 1.7);
  }
  for (let row = 0; row < lanes.length; row++) {
    for (let n = 0; n < 2; n++) {
      const u = (phase * 5 + n / 2 + row * 0.12) % 1;
      const x = 351 + u * 142;
      ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.50 + output * 0.45);
      line(x - 6, lanes[row], x + 6, lanes[row], '#a8d0bb', 3.8);
    }
  }
  ctx.globalAlpha = 1;

  // Housing occlusion is intentional: airborne rings are hidden while they
  // traverse a cartridge, then reappear in the next open air channel.
  for (const event of events) particle(event);
  for (let col = 0; col < 3; col++) {
    const x = filterCenters[col];
    const response = 0.5 + 0.5 * Math.sin(angle * 2 - col * 0.72);
    const active = 0.16 + adsorption * (0.28 + response * 0.22);
    const filter = ctx.createLinearGradient(x - 39, -158, x + 39, 152);
    filter.addColorStop(0, mix([174, 199, 184], [212, 197, 160], active));
    filter.addColorStop(1, mix([135, 172, 164], [183, 167, 139], active));
    box(x - 39, -158, 78, 310, 11, filter, ink, 3.7);
    for (const y of lanes) {
      box(x - 28, y - 11.5, 56, 23, 4.5, '#365362', '#5c7b84', 1.5);
      line(x - 24, y, x + 24, y, '#6b8c95', 1.5);
    }
    for (const offset of [-19, 0, 19]) {
      line(x + offset, -145, x + offset, -134, '#71958b', 1.7);
      line(x + offset, 133, x + offset, 141, '#71958b', 1.7);
    }
  }

  // Dedicated capture pockets preserve separation from every through-flow lane.
  for (const event of events) {
    const left = event.goal - 11;
    box(left, event.y - 14, 22, 28, 5,
      mix([69, 99, 103], [174, 143, 109],
          0.12 + event.captured * (0.35 + adsorption * 0.38)), ink, 2.1);
    ctx.save();
    rounded(left + 3, event.y - 11, 16, 22, 3);
    ctx.clip();
    particle(event);
    ctx.restore();
  }

  // Filter-to-collector conduits terminate in explicit housing ports.
  for (const x of filterCenters) {
    line(x, 153, x, 218, ink, 8);
    line(x, 153, x, 218, '#ae9d83', 4);
    box(x - 10, 170, 20, 15, 4, '#9db7b1', ink, 2);
  }
  box(-259, 214, 518, 91, 14, '#cbd8ce', ink, 4.3);
  const captures = [(events[0].captured + events[3].captured) / 2,
                    events[1].captured, events[2].captured];
  for (let col = 0; col < 3; col++) {
    const x = filterCenters[col];
    box(x - 58, 235, 116, 49, 7, '#91afa9', '#66888a', 2);
    const level = clamp(0.36 + 0.24 * adsorption + 0.12 * output
                     + captures[col] * 0.08 + 0.03 * Math.sin(angle * 2 - col * 0.5));
    box(x - 45, 249, 90, 20, 4, '#557d83', null, 0);
    ctx.save();
    rounded(x - 45, 249, 90, 20, 4);
    ctx.clip();
    const captured = ctx.createLinearGradient(x - 45, 249, x + 45, 269);
    captured.addColorStop(0, '#d5bc96');
    captured.addColorStop(1, '#b89e7d');
    ctx.fillStyle = captured;
    ctx.fillRect(x - 45, 249, 90 * level, 20);
    ctx.restore();
    box(x - 45, 249, 90, 20, 4, null, '#567d7d', 1.3);
  }

  // Vector CO2 label: all paths, no system font or outside asset dependency.
  box(-71, -280, 142, 52, 11, '#365463', ink, 2.8);
  ctx.beginPath();
  ctx.arc(-30, -254, 13, Math.PI * 0.25, Math.PI * 1.75);
  ctx.strokeStyle = '#d9e3d2';
  ctx.lineWidth = 3.2;
  ctx.stroke();
  circle(4, -254, 13, null, '#d9e3d2', 3.2);
  ctx.beginPath();
  ctx.moveTo(25, -253);
  ctx.quadraticCurveTo(26, -260, 32, -260);
  ctx.quadraticCurveTo(39, -260, 39, -254);
  ctx.quadraticCurveTo(39, -250, 32, -246);
  ctx.lineTo(25, -240);
  ctx.lineTo(40, -240);
  ctx.strokeStyle = '#d9e3d2';
  ctx.lineWidth = 2.8;
  ctx.stroke();
  for (const x of [-230, -206, 206, 230]) {
    circle(x, -254, 4.2, '#91b6aa', ink, 1.3);
  }
  for (const x of [-311, 311]) {
    for (const y of [-296, 306]) {
      circle(x, y, 3.5, '#8ca5a8', ink, 1.4);
      line(x - 1.3, y, x + 1.3, y, ink, 1.1);
    }
  }

  ctx.restore();
  ctx.beginPath();
}

/*
 * 05 — WATER LOOP / SMART WATER CONSERVATION
 * Standalone Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: filtration / storage / recirculation.
 * Exact 25-second loop, fixed silhouette, fixed background, no external assets.
 * No blur, shadows, glow, camera movement, or decorative moving particles.
 * Export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * Set the encoding bitrate in the host exporter; Canvas itself renders pixels.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#24495c';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const filtration = emphasis[0];
  const storage = emphasis[1];
  const recirculation = emphasis[2];
  const stored = currentScene === 1 ? smooth(sceneProgress)
               : currentScene === 2 ? 1 - smooth(sceneProgress) : 0;

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function droplet() {
    ctx.beginPath();
    ctx.moveTo(0, -396);
    ctx.bezierCurveTo(-44, -325, -268, -126, -294, 42);
    ctx.bezierCurveTo(-328, 254, -177, 387, 0, 388);
    ctx.bezierCurveTo(177, 387, 328, 254, 294, 42);
    ctx.bezierCurveTo(268, -126, 44, -325, 0, -396);
    ctx.closePath();
  }

  // One closed circulation route, parameterized by actual line and arc lengths.
  // Sections: 0 outlet pipe; 1 reservoir; 2 return pipe; 3 filter interior.
  const segments = [];
  function L(x0, y0, x1, y1, section) {
    segments.push({ kind: 0, x0, y0, x1, y1, section,
                    length: Math.hypot(x1 - x0, y1 - y0) });
  }
  function A(cx, cy, r, a0, a1, section) {
    segments.push({ kind: 1, cx, cy, r, a0, a1, section,
                    length: Math.abs(a1 - a0) * r });
  }
  L(-106, 35, -165, 35, 0);
  A(-165, 60, 25, -Math.PI / 2, -Math.PI, 0);
  L(-190, 60, -190, 187, 0);
  A(-165, 187, 25, Math.PI, Math.PI / 2, 0);
  L(-165, 212, -132, 212, 0);
  L(-132, 212, 132, 212, 1);
  L(132, 212, 165, 212, 2);
  A(165, 187, 25, Math.PI / 2, 0, 2);
  L(190, 187, 190, -90, 2);
  A(165, -90, 25, 0, -Math.PI / 2, 2);
  L(165, -115, 106, -115, 2);
  L(106, -115, 20, -115, 3);
  A(20, -95, 20, -Math.PI / 2, -Math.PI, 3);
  L(0, -95, 0, 15, 3);
  A(-20, 15, 20, 0, Math.PI / 2, 3);
  L(-20, 35, -106, 35, 3);
  const routeLength = segments.reduce((sum, s) => sum + s.length, 0);

  function point(s, u) {
    if (s.kind === 0) return [s.x0 + (s.x1 - s.x0) * u, s.y0 + (s.y1 - s.y0) * u];
    const a = s.a0 + (s.a1 - s.a0) * u;
    return [s.cx + s.r * Math.cos(a), s.cy + s.r * Math.sin(a)];
  }

  function trace(section) {
    let first = true;
    ctx.beginPath();
    for (const s of segments) {
      if (s.section !== section) continue;
      if (first) {
        const p = point(s, 0);
        ctx.moveTo(p[0], p[1]);
        first = false;
      }
      if (s.kind === 0) ctx.lineTo(s.x1, s.y1);
      else ctx.arc(s.cx, s.cy, s.r, s.a0, s.a1, s.a1 < s.a0);
    }
  }

  const packets = [];
  for (let n = 0; n < 12; n++) {
    let d = ((phase * 2 + n / 12) % 1) * routeLength;
    let s = segments[segments.length - 1];
    for (const candidate of segments) {
      s = candidate;
      if (d <= s.length) break;
      d -= s.length;
    }
    const p = point(s, clamp(d / s.length));
    packets.push({ x: p[0], y: p[1], section: s.section });
  }

  function drawPackets(section) {
