  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 6;
  ctx.stroke();
  ctx.save();
  ctx.scale(0.93, 0.93);
  droplet();
  ctx.strokeStyle = '#81afb9';
  ctx.lineWidth = 2.1;
  ctx.stroke();
  ctx.restore();

