    trace(section);
    ctx.strokeStyle = ink;
    ctx.lineWidth = 14;
    ctx.stroke();
    trace(section);
    const active = section === 0 ? filtration : recirculation;
    ctx.strokeStyle = mix([117, 163, 174], [70, 132, 152], 0.25 + 0.60 * active);
    ctx.lineWidth = 8;
    ctx.stroke();
    drawPackets(section);
