  const filterBody = ctx.createLinearGradient(-106, -146, 106, 64);
  filterBody.addColorStop(0, '#e0e9df');
  filterBody.addColorStop(1, '#bfd8d4');
  box(-106, -146, 212, 210, 18, filterBody, ink, 4.5);
  trace(3);
  ctx.strokeStyle = '#87afb3';
  ctx.lineWidth = 7;
  ctx.stroke();
