  box(-132, 135, 264, 145, 18, '#d5e4df', ink, 4.5);
  ctx.save();
  rounded(-126, 141, 252, 133, 12);
  ctx.clip();
  const waterY = 184 - stored * 21;
  ctx.beginPath();
  for (let j = 0; j <= 48; j++) {
    const u = j / 48;
    const x = -126 + u * 252;
    const y = waterY + 3.6 * Math.sin(TAU * u + angle * 3);
    if (j === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.lineTo(126, 274);
  ctx.lineTo(-126, 274);
  ctx.closePath();
  const water = ctx.createLinearGradient(0, 157, 0, 274);
  water.addColorStop(0, '#7dbac1');
  water.addColorStop(1, '#4e91a6');
  ctx.fillStyle = water;
  ctx.fill();
  trace(1);
  ctx.strokeStyle = '#4b899c';
  ctx.lineWidth = 2;
  ctx.stroke();
  drawPackets(1);
  ctx.restore();
  box(-132, 135, 264, 145, 18, null, ink, 4.5);
  for (const y of [158, 183, 240, 258]) {
    line(-110, y, -96, y, '#4d7e8d', 1.9);
  }
  box(-141, 201, 16, 22, 4, '#b1cfd0', ink, 2.5);
  box(125, 201, 16, 22, 4, '#b1cfd0', ink, 2.5);

  // Integrated six-segment conservation gauge, without text or emissive effects.
  box(-110, 302, 220, 40, 11, '#d9e7dc', ink, 3.7);
  const level = 0.68 + 0.07 * filtration * Math.sin(angle)
                     + 0.10 * storage * Math.sin(angle * 2 - 0.3)
                     + 0.035 * recirculation * Math.sin(angle * 3);
  for (let n = 0; n < 6; n++) {
    const active = smooth((level - (n + 0.25) / 6) * 6);
    box(-90 + n * 31, 312, 25, 20, 3.5,
      mix([157, 190, 188], [54, 123, 140], active), '#779f9f', 1.15);
  }

  ctx.restore();
  ctx.beginPath();
}

/*
 * 06 — EFFICIENT BUILDING / SUSTAINABLE ARCHITECTURE
 * Standalone Canvas 2D: draw(ctx, timeInSeconds, width, height).
 * 25 seconds; three scenes: active building / energy routing / efficient use.
 * Exact 25-second loop, fixed front elevation, static background, no assets.
 * No blur, shadows, glow, perspective, people, or camera movement.
 * Export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * Set the encoding bitrate in the host exporter; Canvas itself renders pixels.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#2b3d58';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const activity = emphasis[0];
  const routing = emphasis[1];
  const efficient = emphasis[2];

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // Fixed slate / lavender gradient. No part of the background is animated.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#c0cbe0');
  background.addColorStop(0.5, '#a8bad2');
  background.addColorStop(1, '#8faac0');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);

  for (const side of [-1, 1]) {
    for (const y of [-380, 380]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 621, y + sy * 22);
      ctx.lineTo(side * 621, y);
      ctx.lineTo(side * 599, y);
      ctx.strokeStyle = 'rgba(43,61,88,0.18)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }

  const shell = ctx.createLinearGradient(-307, -272, 307, 313);
  shell.addColorStop(0, '#e1e7e8');
  shell.addColorStop(1, '#b9cbd5');
  box(-307, -272, 614, 585, 17, shell, ink, 5.5);
  box(-285, -250, 570, 546, 9, '#c7d7dd', '#829caf', 2.8);

  // Dedicated thermal bands remain separate from the facade and glass areas.
  const thermal = mix([139, 169, 180], [62, 128, 132], 0.15 + 0.72 * routing);
  for (const side of [-1, 1]) {
    line(side * 297, -252, side * 297, 297, thermal, 4.2);
  }

  // The central energy bus fits the 18-unit gap between glass columns.
  line(0, -247, 0, 207, '#8aabb0', 6.8);
  line(0, -247, 0, 207, '#638f9a', 2.6);
  for (let n = 0; n < 5; n++) {
    const u = (phase * 5 + n / 5) % 1;
    ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.20 + 0.74 * routing);
    circle(0, -245 + u * 450, 2.2, '#e7d9b2', null, 0);
  }
  ctx.globalAlpha = 1;

  for (let row = 0; row < 5; row++) {
    const y = -209 + row * 82;
    const busY = y - 9;
    line(-245, busY, 245, busY, '#88a7ae', 1.8);
    circle(0, busY, 3.3, '#739b9e', ink, 0.9);

    // Each branch touches the top of its consumer, with clear gutters elsewhere.
    for (let col = 0; col < 6; col++) {
      const x = -237 + col * 82;
      line(x + 32, busY, x + 32, y, '#88a7ae', 1.8);
    }
    for (const side of [-1, 1]) {
      for (let n = 0; n < 2; n++) {
        const u = (phase * 4 + n / 2 + row * 0.13) % 1;
        ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.20 + 0.70 * routing);
        circle(side * (12 + u * 225), busY, 1.9, '#e6d6ac', null, 0);
      }
    }
    ctx.globalAlpha = 1;

    for (let col = 0; col < 6; col++) {
      const x = -237 + col * 82;
      const occupancy = 0.5 + 0.5 * Math.sin(angle * 2 - row * 0.58 - col * 0.44);
      const distribution = 0.5 + 0.5 * Math.sin(angle * 3 - row * 0.64);
      const lowLoad = 0.5 + 0.5 * Math.sin(angle * 2 - col * 0.36 - row * 0.27);
      const use = clamp(0.14 + activity * (0.20 + 0.48 * occupancy)
                     + routing * (0.35 + 0.16 * distribution)
                     + efficient * (0.08 + 0.12 * lowLoad));
      const glass = ctx.createLinearGradient(x, y, x + 64, y + 64);
      glass.addColorStop(0, mix([113, 161, 179], [221, 223, 185], use));
      glass.addColorStop(1, mix([79, 127, 152], [179, 204, 185], use));
      box(x, y, 64, 64, 5, glass, '#3e5c75', 2.8);
      line(x + 32, y + 7, x + 32, y + 57, '#668998', 1.4);
      line(x + 7, y + 40, x + 57, y + 40, '#668998', 1.3);
    }
  }

  // Fixed ground-floor entrance and ventilation details; no figures or signage.
  box(-64, 214, 128, 78, 7, '#7695a8', ink, 3.2);
  line(0, 220, 0, 286, ink, 2.1);
  for (const x of [-12, 12]) line(x, 248, x, 262, '#ccdcd8', 2.8);
  for (const x of [-237, 109]) {
    box(x, 229, 128, 54, 6, '#b0c6d0', '#668494', 2.1);
    for (let row = 0; row < 4; row++) {
      line(x + 13, 242 + row * 9, x + 115, 242 + row * 9, '#789aa8', 1.6);
    }
  }

  // Roof cornice, mounting feet, and compact front-facing renewable-energy panel.
  box(-330, -288, 660, 30, 7, '#d4dfe1', ink, 4.3);
  for (const x of [-112, 112]) box(x - 7, -300, 14, 17, 3, '#a6bfca', ink, 2.3);
  line(0, -298, 0, -288, '#638f9a', 4.5);
  box(-165, -374, 330, 78, 10, '#d8e4df', ink, 4.4);
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 6; col++) {
      const x = -147 + col * 50;
      const y = -360 + row * 27;
      const response = 0.5 + 0.5 * Math.cos(angle * 2 - col * 0.35 - row * 0.3);
      const fill = mix([73, 129, 147], [119, 171, 171], 0.22 + response * 0.42);
      box(x, y, 44, 21, 3, fill, '#335a70', 1.4);
      line(x + 22, y + 4, x + 22, y + 17, '#a1c2bb', 1.1);
    }
  }

  // Integrated plinth and energy-use gauge. Low-load scene uses fewer segments.
  box(-330, 306, 660, 94, 17, '#dce5e1', ink, 5.5);
  box(-214, 331, 429, 46, 9, '#bdcfcf', '#96adb1', 1.8);
  const load = 0.74 * activity + 0.59 * routing + 0.43 * efficient
             + 0.035 * Math.sin(angle * 2) * (0.8 - 0.4 * efficient);
  for (let n = 0; n < 10; n++) {
    const active = smooth((load - (n + 0.25) / 10) * 10);
    box(-197 + n * 40, 342, 27, 24, 3.5,
      mix([157, 181, 182], [60, 125, 139], active), '#829fa5', 1.15);
  }
  ctx.beginPath();
  ctx.moveTo(-264, 333);
  ctx.lineTo(-282, 357);
  ctx.lineTo(-268, 357);
  ctx.lineTo(-274, 375);
  ctx.lineTo(-250, 348);
  ctx.lineTo(-265, 348);
  ctx.lineTo(-259, 333);
  ctx.closePath();
  ctx.fillStyle = '#c6c59c';
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 2.5;
  ctx.stroke();
  for (let n = 0; n < 3; n++) {
    circle(266, 342 + n * 12, 3.6,
      mix([148, 174, 175], [76, 139, 136], 0.25 + efficient * 0.65), ink, 1);
  }

  ctx.restore();
  ctx.beginPath();
}

/*
 * 03 — ENERGY RESERVE / CLEAN BATTERY STORAGE
 * Pure, standalone Canvas 2D; draw(ctx, timeInSeconds, width, height).
 * 25 seconds, three scenes, seamless 25-second loop. No external resources.
 * Scenes: charge four modules / balance the modules / deliver stored energy.
 * Fixed background and geometry. No glow, blur, shadows, or camera movement.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * The video encoder must be configured by the host; Canvas renders pixels only.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const angle = TAU * phase;
  const scale = minSide / 1000;
  const ink = '#142e36';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const charge = emphasis[0];
  const balancing = emphasis[1];
  const delivery = emphasis[2];

  // Capacity is continuous, with zero slope and acceleration at scene joins.
  // Zero-sum module deviations preserve the mean during the balancing scene.
  const e = smooth(sceneProgress);
  const initialDeviation = [-0.055, 0.055, -0.028, 0.028];
  const peakDeviation = [-0.09, 0.09, -0.055, 0.055];
  let meanLevel;
  const deviations = [0, 0, 0, 0];
  if (currentScene === 0) {
    meanLevel = 0.42 + 0.34 * e;
    for (let n = 0; n < 4; n++) {
      deviations[n] = initialDeviation[n]
                    + (peakDeviation[n] - initialDeviation[n]) * e;
    }
  } else if (currentScene === 1) {
    meanLevel = 0.76;
    for (let n = 0; n < 4; n++) deviations[n] = peakDeviation[n] * (1 - e);
  } else {
    meanLevel = 0.76 - 0.34 * e;
    for (let n = 0; n < 4; n++) deviations[n] = initialDeviation[n] * e;
  }

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function box(x, y, w, h, r, fill, stroke, lw) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }

  // Rounded, separated input and output conductors, drawn behind their ports.
  function cablePath(output) {
    ctx.beginPath();
    if (output) {
      ctx.moveTo(258, -82);
      ctx.lineTo(366, -82);
      ctx.arc(366, -54, 28, -Math.PI / 2, 0);
      ctx.lineTo(394, 52);
      ctx.arc(422, 52, 28, Math.PI, Math.PI / 2, true);
      ctx.lineTo(546, 80);
    } else {
      ctx.moveTo(-546, -80);
      ctx.lineTo(-422, -80);
      ctx.arc(-422, -52, 28, -Math.PI / 2, 0);
      ctx.lineTo(-394, 54);
      ctx.arc(-366, 54, 28, Math.PI, Math.PI / 2, true);
      ctx.lineTo(-258, 82);
    }
  }

  function cablePoint(u, output) {
    const aLen = 14 * Math.PI;
    const first = output ? 108 : 124;
    const last = output ? 124 : 108;
    const length = first + aLen + 106 + aLen + last;
    let d = u * length;
    let x, y;
    if (d <= first) {
      x = (output ? 258 : -546) + d;
      y = output ? -82 : -80;
    } else if ((d -= first) <= aLen) {
      const a = -Math.PI / 2 + d / 28;
      x = (output ? 366 : -422) + 28 * Math.cos(a);
      y = (output ? -54 : -52) + 28 * Math.sin(a);
    } else if ((d -= aLen) <= 106) {
      x = output ? 394 : -394;
      y = (output ? -54 : -52) + d;
    } else if ((d -= 106) <= aLen) {
      const a = Math.PI - d / 28;
      x = (output ? 422 : -366) + 28 * Math.cos(a);
      y = (output ? 52 : 54) + 28 * Math.sin(a);
    } else {
      d -= aLen;
      x = (output ? 422 : -366) + d;
      y = output ? 80 : 82;
    }
    return [x, y];
  }

  // The internal U bus connects modules through dedicated side gutters.
  function busPath() {
    ctx.beginPath();
    ctx.moveTo(-221, -163);
    ctx.lineTo(-221, 299);
    ctx.arc(-205, 299, 16, Math.PI, Math.PI / 2, true);
    ctx.lineTo(205, 315);
    ctx.arc(205, 299, 16, Math.PI / 2, 0, true);
    ctx.lineTo(221, -163);
  }

  function busPoint(u) {
    const aLen = 8 * Math.PI;
    const total = 462 + aLen + 410 + aLen + 462;
    let d = u * total;
    if (d <= 462) return [-221, -163 + d];
    if ((d -= 462) <= aLen) {
      const a = Math.PI - d / 16;
      return [-205 + 16 * Math.cos(a), 299 + 16 * Math.sin(a)];
    }
    if ((d -= aLen) <= 410) return [-205 + d, 315];
    if ((d -= 410) <= aLen) {
      const a = Math.PI / 2 - d / 16;
      return [205 + 16 * Math.cos(a), 299 + 16 * Math.sin(a)];
    }
    d -= aLen;
    return [221, 299 - d];
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // Every background value is static and independent of the timeline.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#152630');
  background.addColorStop(0.5, '#213b40');
  background.addColorStop(1, '#38554f');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);

  for (const side of [-1, 1]) {
    for (const y of [-383, 383]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 643, y + sy * 22);
      ctx.lineTo(side * 643, y);
      ctx.lineTo(side * 621, y);
      ctx.strokeStyle = 'rgba(188,211,191,0.20)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }

  // Scene emphasis changes the flow strength, never the path or direction.
  for (const output of [false, true]) {
    cablePath(output);
    ctx.strokeStyle = ink;
    ctx.lineWidth = 12;
    ctx.stroke();
    cablePath(output);
    ctx.strokeStyle = '#7fa797';
    ctx.lineWidth = 6;
    ctx.stroke();
    for (let n = 0; n < 3; n++) {
      const u = (phase * 4 + n / 3) % 1;
      const p = cablePoint(u, output);
      const activity = output ? delivery : charge;
      ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.24 + 0.72 * activity);
      circle(p[0], p[1], 2.6, '#e5ce97', null, 0);
    }
    ctx.globalAlpha = 1;
  }

  // Fixed end terminals, attached to the circuit rather than floating details.
  for (const output of [false, true]) {
    const x = output ? 537 : -575;
    const y = output ? 44 : -116;
    box(x, y, 38, 72, 10, '#b6cbb7', ink, 3.7);
    for (let n = 0; n < 3; n++) {
      line(x + 12, y + 19 + n * 17, x + 26, y + 19 + n * 17, '#547d72', 2.5);
    }
  }

  // Battery top terminal and shell are front-elevation, flat-vector shapes.
  box(-86, -364, 172, 48, 10, '#a9c0ad', ink, 5);
  for (const x of [-44, 0, 44]) line(x, -353, x, -332, '#77988a', 2.2);
  const shell = ctx.createLinearGradient(-258, -320, 258, 364);
  shell.addColorStop(0, '#d9e6d6');
  shell.addColorStop(1, '#b7cdb8');
  box(-258, -320, 516, 684, 38, shell, ink, 6);
  box(-232, -292, 464, 630, 23, '#24474b', ink, 3.2);

  // Side contacts cover the circuit ends intentionally, like real connectors.
  box(-269, 68, 22, 28, 5, '#acc8b6', ink, 3);
  box(247, -96, 22, 28, 5, '#acc8b6', ink, 3);

  // Inlaid header: a non-emissive power glyph and four fixed status indicators.
  ctx.beginPath();
  ctx.moveTo(-174, -277);
  ctx.lineTo(-190, -254);
  ctx.lineTo(-177, -254);
  ctx.lineTo(-182, -237);
  ctx.lineTo(-161, -262);
  ctx.lineTo(-175, -262);
  ctx.lineTo(-169, -277);
  ctx.closePath();
  ctx.fillStyle = '#c6d19b';
  ctx.fill();
  ctx.strokeStyle = ink;
  ctx.lineWidth = 2.1;
  ctx.stroke();
  line(-207, -231, 207, -231, '#50736c', 1.7);
  for (let n = 0; n < 4; n++) {
    const deviation = Math.abs(deviations[n]);
    const settled = clamp(1 - deviation * 8);
    const pip = mix([147, 177, 148], [209, 216, 166], settled);
    circle(99 + n * 25, -257, 5.5, pip, ink, 1.5);
  }

  busPath();
  ctx.strokeStyle = '#112e36';
  ctx.lineWidth = 8;
  ctx.stroke();
  busPath();
  ctx.strokeStyle = '#91af94';
  ctx.lineWidth = 4.8;
  ctx.stroke();
  for (let n = 0; n < 10; n++) {
    const u = (phase * 2 + n / 10) % 1;
    const p = busPoint(u);
    ctx.globalAlpha = Math.pow(Math.sin(Math.PI * u), 2) * (0.20 + 0.76 * balancing);
    circle(p[0], p[1], 2.1, '#e5d29d', null, 0);
  }
  ctx.globalAlpha = 1;

  // Four modules, identical sizes and fixed 24-unit vertical clearances.
  for (let row = 0; row < 4; row++) {
    const y = -217 + row * 132;
    const level = meanLevel + deviations[row];
    for (const side of [-1, 1]) {
      line(side * 207, y + 54, side * 221, y + 54, '#91af94', 3.8);
    }
    const module = ctx.createLinearGradient(-207, y, 207, y + 108);
    module.addColorStop(0, '#31585a');
    module.addColorStop(1, '#254a50');
    box(-207, y, 414, 108, 13, module, ink, 3.7);

    const response = 0.5 + 0.5 * Math.cos(angle * 4 - row * Math.PI / 2);
    circle(-177, y + 54, 7.5,
      mix([130, 163, 136], [212, 215, 158], 0.25 + 0.55 * response), ink, 1.8);

    // Each level is clipped to its fixed slot. No outline is scaled or deformed.
    for (let slot = 0; slot < 6; slot++) {
      const x = -146 + slot * 55;
      box(x, y + 24, 46, 60, 5.5, '#1d3e44', null, 0);
      const amount = clamp(level * 6 - slot);
      if (amount > 0) {
        ctx.save();
        rounded(x, y + 24, 46, 60, 5.5);
        ctx.clip();
        const stored = ctx.createLinearGradient(x, y + 24, x, y + 84);
        stored.addColorStop(0, '#c0ce92');
        stored.addColorStop(1, '#81ad97');
        ctx.fillStyle = stored;
        ctx.fillRect(x, y + 24, amount * 46, 60);
        ctx.restore();
      }
      box(x, y + 24, 46, 60, 5.5, null, '#789783', 1.35);
    }
  }

  // Frame fasteners sit in their own rim, away from all internal motion.
  for (const x of [-211, 211]) {
    for (const y of [-306, 350]) {
      circle(x, y, 3.7, '#94af97', ink, 1.5);
      line(x - 1.5, y, x + 1.5, y, ink, 1.1);
    }
  }
  ctx.restore();
  ctx.beginPath();
}

/*
 * 04 — CIRCULAR MATERIAL / CONTINUOUS RECYCLING
 * Pure, standalone Canvas 2D; draw(ctx, timeInSeconds, width, height).
 * 25 seconds, three scenes, seamless 25-second loop. No external resources.
 * Scenes: collect mixed material / sort into uniform tiles / redistribute.
 * Three fixed curved arrows; material travels only in dedicated ribbon lanes.
 * Static background. No glow, blur, shadows, or camera movement.
 * Video export target: 3840 x 2160, 60 fps, 100,000,000 bits per second.
 * The video encoder must be configured by the host; Canvas renders pixels only.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(minSide > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  const phase = loopT / duration;
  const scale = minSide / 1000;
  const ink = '#173e35';
  const clamp = (v, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, v));
  const smooth = v => {
    const u = clamp(v);
    return u * u * u * (u * (u * 6 - 15) + 10);
  };
  const mix = (a, b, u) => 'rgb(' + [0, 1, 2].map(
    i => Math.round(a[i] + (b[i] - a[i]) * u)
  ).join(',') + ')';
  const transition = smooth((sceneProgress - 0.78) / 0.22);
  const emphasis = [0, 0, 0];
  emphasis[currentScene] = 1 - transition;
  emphasis[(currentScene + 1) % sceneCount] = transition;
  const standardize = currentScene === 1 ? smooth(sceneProgress)
                    : currentScene === 2 ? 1 - smooth(sceneProgress) : 0;
  const R = 270;
  const innerR = 226;
  const outerR = 314;
  const start = -Math.PI / 2;
  const shoulder = start + 82 * Math.PI / 180;
  const tip = start + 108 * Math.PI / 180;

  function polar(r, a) { return [r * Math.cos(a), r * Math.sin(a)]; }

  function arrowPath() {
    const p0 = polar(outerR, start);
    const p1 = polar(outerR + 20, shoulder);
    const p2 = polar(R, tip);
    const p3 = polar(innerR - 20, shoulder);
    const p4 = polar(innerR, shoulder);
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    ctx.arc(0, 0, outerR, start, shoulder);
    ctx.lineTo(p1[0], p1[1]);
    ctx.lineTo(p2[0], p2[1]);
    ctx.lineTo(p3[0], p3[1]);
    ctx.lineTo(p4[0], p4[1]);
    ctx.arc(0, 0, innerR, shoulder, start, true);
    ctx.closePath();
  }

  function rounded(x, y, w, h, r) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + q, y);
    ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q);
    ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h);
    ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q);
    ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y);
    ctx.closePath();
  }

  function line(x1, y1, x2, y2, stroke, lw) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lw;
    ctx.stroke();
  }

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  // Static forest / sage gradient; no background animation or particles.
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#193e36');
  background.addColorStop(0.5, '#345e4e');
  background.addColorStop(1, '#64866b');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2, height / 2);
  ctx.scale(scale, scale);

  for (const side of [-1, 1]) {
    for (const y of [-365, 365]) {
      const sy = y < 0 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(side * 601, y + sy * 22);
      ctx.lineTo(side * 601, y);
      ctx.lineTo(side * 579, y);
      ctx.strokeStyle = 'rgba(214,226,197,0.22)';
      ctx.lineWidth = 1.8;
      ctx.stroke();
    }
  }

  // A uniform subject scale keeps the circular icon prominent in a 16:9 frame.
  ctx.scale(1.14, 1.14);

  // A compact, integrated material-sorting core. Its fixed windows retain
  // generous clearances throughout the change from mixed to uniform material.
  rounded(-115, -69, 230, 138, 17);
  const core = ctx.createLinearGradient(-115, -69, 115, 69);
  core.addColorStop(0, '#375f4e');
  core.addColorStop(1, '#426952');
  ctx.fillStyle = core;
  ctx.fill();
  ctx.strokeStyle = '#93ae8e';
  ctx.lineWidth = 2.9;
  ctx.stroke();

  const samples = [[28, 46], [44, 20], [32, 36]];
  const sampleColors = [[230, 223, 180], [194, 215, 199], [220, 227, 195]];
  for (let n = 0; n < 3; n++) {
    const x = (n - 1) * 64;
    const w = samples[n][0] + (36 - samples[n][0]) * standardize;
    const h = samples[n][1] + (36 - samples[n][1]) * standardize;
    rounded(x - w / 2, -h / 2 - 5, w, h, 5);
    const swatch = ctx.createLinearGradient(x - w / 2, -h / 2, x + w / 2, h / 2);
    swatch.addColorStop(0, mix(sampleColors[n], [228, 231, 202], standardize));
    swatch.addColorStop(1, mix(sampleColors[n], [205, 221, 188],
                             0.12 + standardize * 0.42));
    ctx.fillStyle = swatch;
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 2.3;
    ctx.stroke();
    for (const side of [-1, 1]) {
      line(x + side * w * 0.16, -5 - h * 0.20,
           x + side * w * 0.16, -5 + h * 0.20, '#7d9b7b', 1.2);
    }
    // Fixed alignment marks emphasize that only the material is being sorted.
    line(x - 8, 42, x + 8, 42, '#96b18e', 1.7);
  }

  const paletteTop = [[176, 201, 170], [206, 217, 185], [148, 187, 163]];
  const paletteBottom = [[140, 177, 151], [171, 195, 164], [108, 160, 143]];
  for (let n = 0; n < 3; n++) {
    ctx.save();
    ctx.rotate(n * TAU / 3);
    const response = emphasis[n] * 0.26;
    const ribbon = ctx.createLinearGradient(-40, -325, 295, 120);
    ribbon.addColorStop(0, mix(paletteTop[n], [227, 229, 199], response));
    ribbon.addColorStop(1, mix(paletteBottom[n], [184, 207, 175], response));
    arrowPath();
    ctx.fillStyle = ribbon;
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 5.6;
    ctx.stroke();

    // Double inset rails frame the material lane without entering its swept area.
    for (const radius of [246, 294]) {
      ctx.beginPath();
      ctx.arc(0, 0, radius, start + 9 * Math.PI / 180,
              start + 73 * Math.PI / 180);
      ctx.strokeStyle = 'rgba(38,83,65,0.40)';
      ctx.lineWidth = 1.7;
      ctx.stroke();
    }

    // Registration inlays stay in the outer margin, clear of all material.
    for (const degrees of [22, 40, 58]) {
      const a = start + degrees * Math.PI / 180;
      const p1 = polar(303, a);
      const p2 = polar(309, a);
      line(p1[0], p1[1], p2[0], p2[1], 'rgba(36,77,61,0.48)', 1.7);
    }
    ctx.restore();
  }

  // Twelve equally spaced material packets; one complete circuit per 25 seconds.
  // The fade gates hide handoffs inside arrow ends and preserve all three gaps.
  const dimensions = [[20, 24], [32, 12], [18, 20]];
  const materialColors = [[230, 223, 180], [194, 215, 199], [220, 227, 195]];
  for (let n = 0; n < 12; n++) {
    const orbit = (phase + n / 12) % 1;
    const localDegrees = ((orbit * 3) % 1) * 120;
    const opacity = smooth((localDegrees - 6) / 9)
                  * (1 - smooth((localDegrees - 69) / 9));
    if (opacity <= 0) continue;
    const a = start + orbit * TAU;
    const kind = n % 3;
    const w = dimensions[kind][0] + (22 - dimensions[kind][0]) * standardize;
    const h = dimensions[kind][1] + (22 - dimensions[kind][1]) * standardize;
    const radius = 3 + standardize;
    const p = polar(R, a);

    ctx.save();
    ctx.globalAlpha = opacity;
    ctx.translate(p[0], p[1]);
    ctx.rotate(a + Math.PI / 2);
    rounded(-w / 2, -h / 2, w, h, radius);
    const material = ctx.createLinearGradient(-w / 2, -h / 2, w / 2, h / 2);
    material.addColorStop(0, mix(materialColors[kind], [228, 231, 202], standardize));
    material.addColorStop(1, mix(materialColors[kind], [205, 221, 188],
                               0.12 + standardize * 0.42));
    ctx.fillStyle = material;
    ctx.fill();
    ctx.strokeStyle = ink;
    ctx.lineWidth = 2.1;
    ctx.stroke();

    // Fine material detail fits every shape throughout the controlled morph.
    line(-w * 0.16, -h * 0.20, -w * 0.16, h * 0.20, '#7d9b7b', 1.1);
    line(w * 0.16, -h * 0.20, w * 0.16, h * 0.20, '#7d9b7b', 1.1);
    ctx.restore();
  }

  ctx.restore();
  ctx.beginPath();
}

/*
 * Sustainability 03 — Circular Material Station
 * 25 seconds, 3 scenes, 3840 x 2160, 60 fps; time is in SECONDS.
 * Original, asset-free, deterministic Canvas 2D animation.
 * Background is static. No blur, glow, additive light, or external dependencies.
 * Video export target: 100,000,000 bits/second, configured in the encoder.
 * Drawing code does not encode video or enforce a video bitrate.
 */
const CircularMaterialStation = (() => {

  const TAU = Math.PI * 2;
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const fract = v => v - Math.floor(v);
  const mix = (a, b, p) => a + (b - a) * p;
  const ease = p => {
    p = clamp(p);
    return p * p * p * (p * (p * 6 - 15) + 10);
  };
  const ramp = (a, b, v) => ease((v - a) / (b - a));

  function color(a, b, p) {
    const ca = parseInt(a.slice(1), 16), cb = parseInt(b.slice(1), 16);
    p = clamp(p);
    return `rgb(${Math.round(mix((ca >> 16) & 255, (cb >> 16) & 255, p))},${Math.round(mix((ca >> 8) & 255, (cb >> 8) & 255, p))},${Math.round(mix(ca & 255, cb & 255, p))})`;
  }
  function rounded(ctx, x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath(); ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(ctx, x, y, w, h, r, fill, stroke, lw = 4) {
    rounded(ctx, x, y, w, h, r);
    if (fill) {ctx.fillStyle = fill; ctx.fill();}
    if (stroke) {ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke();}
  }
  function circle(ctx, x, y, r, fill, stroke, lw = 4) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) {ctx.fillStyle = fill; ctx.fill();}
    if (stroke) {ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke();}
  }
  function line(ctx, points, ink, lw = 4) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = ink; ctx.lineWidth = lw; ctx.stroke();
  }
  function screw(ctx, x, y, ink, face) {
    circle(ctx, x, y, 5, face, ink, 2);
    line(ctx, [[x - 2, y], [x + 2, y]], ink, 1.5);
  }
  function bolt(ctx, x, y, s, fill) {
    ctx.beginPath(); ctx.moveTo(x + 2 * s, y - 16 * s);
    ctx.lineTo(x - 11 * s, y + 2 * s);
    ctx.lineTo(x - s, y + 2 * s);
    ctx.lineTo(x - 4 * s, y + 16 * s);
    ctx.lineTo(x + 11 * s, y - 4 * s);
    ctx.lineTo(x + s, y - 4 * s);
    ctx.closePath(); ctx.fillStyle = fill; ctx.fill();
  }
  function packet(ctx, x0, y0, x1, y1, p, alpha, ink, length = 16, lw = 4) {
    alpha *= ramp(0, 0.08, p) * (1 - ramp(0.92, 1, p));
    if (alpha <= 0) return;
    const d = Math.hypot(x1 - x0, y1 - y0);
    const h = length / (2 * d);
    const a = clamp(p - h), b = clamp(p + h);
    ctx.save(); ctx.globalAlpha *= alpha;
    line(ctx, [[mix(x0, x1, a), mix(y0, y1, a)], [mix(x0, x1, b), mix(y0, y1, b)]], ink, lw);
    ctx.restore();
  }
  function paintBackground(ctx, width, height, palette, tint) {
    // Fixed geometry and fixed gradient stops: the entire background is static.
    const g = ctx.createLinearGradient(0, 0, width, height);
    g.addColorStop(0, palette[0]);
    g.addColorStop(0.52, palette[1]);
    g.addColorStop(1, palette[2]);
    ctx.fillStyle = g; ctx.fillRect(0, 0, width, height);
    ctx.beginPath(); ctx.moveTo(0, height * 0.77);
    ctx.bezierCurveTo(width * 0.09, height * 0.65, width * 0.20, height * 0.85, width * 0.31, height);
    ctx.lineTo(0, height); ctx.closePath(); ctx.fillStyle = tint; ctx.fill();
    ctx.beginPath(); ctx.moveTo(width * 0.78, 0);
    ctx.bezierCurveTo(width * 0.86, height * 0.16, width * 0.94, height * 0.22, width, height * 0.20);
    ctx.lineTo(width, 0); ctx.closePath(); ctx.fill();
  }

  function fragment(ctx, x, y, type, s, fill, ink) {
    if (type === 0) {
      box(ctx, x - 15 * s, y - 11 * s, 30 * s, 22 * s, 4 * s, fill, ink, 2.5);
      line(ctx, [[x - 8 * s, y - 3 * s], [x + 7 * s, y - 3 * s]], ink, 1.3);
      line(ctx, [[x - 8 * s, y + 4 * s], [x + 3 * s, y + 4 * s]], ink, 1.3);
    } else if (type === 1) {
      box(ctx, x - 12 * s, y - 15 * s, 24 * s, 30 * s, 8 * s, fill, ink, 2.5);
      line(ctx, [[x - 6 * s, y - 7 * s], [x + 5 * s, y - 7 * s]], ink, 1.3);
    } else {
      ctx.beginPath();
      for (let i = 0; i < 6; i++) {
        const a = Math.PI / 6 + i * TAU / 6;
        const px = x + Math.cos(a) * 16 * s, py = y + Math.sin(a) * 16 * s;
        if (!i) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath(); ctx.fillStyle = fill; ctx.fill();
      ctx.strokeStyle = ink; ctx.lineWidth = 2.5; ctx.stroke();
      circle(ctx, x, y, 4 * s, null, ink, 1.5);
    }
  }
  function circularArrows(ctx, x, y, radius, angle, ink) {
    // Three separate curved arrows, with ample clear gaps between their tips.
    for (let i = 0; i < 3; i++) {
      const a0 = angle + i * TAU / 3, a1 = a0 + TAU / 3 - 0.51;
      ctx.beginPath(); ctx.arc(x, y, radius, a0, a1);
      ctx.strokeStyle = ink; ctx.lineWidth = 3.5; ctx.stroke();
      const px = x + Math.cos(a1) * radius, py = y + Math.sin(a1) * radius;
      const tx = -Math.sin(a1), ty = Math.cos(a1);
      const nx = Math.cos(a1), ny = Math.sin(a1);
      ctx.beginPath(); ctx.moveTo(px + tx * 4.6, py + ty * 4.6);
      ctx.lineTo(px - tx * 2.8 + nx * 4, py - ty * 2.8 + ny * 4);
      ctx.lineTo(px - tx * 2.8 - nx * 4, py - ty * 2.8 - ny * 4);
      ctx.closePath(); ctx.fillStyle = ink; ctx.fill();
    }
  }
  function roller(ctx, x, y, radius, angle, ink) {
    circle(ctx, x, y, radius, '#A9BFA4', ink, 2.6);
    const dx = Math.cos(angle) * radius * 0.55, dy = Math.sin(angle) * radius * 0.55;
    line(ctx, [[x - dx, y - dy], [x + dx, y + dy]], ink, 2.1);
    circle(ctx, x, y, 2.4, ink, null);
  }
  return {TAU, clamp, fract, mix, ease, ramp, color, rounded, box, circle, line, screw, bolt, packet, paintBackground, fragment, circularArrows, roller};
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const M = CircularMaterialStation;
  const phase = M.TAU * loopT / duration;
  const handoff = M.ramp(0.89, 1, sceneProgress);
  const weights = [0, 0, 0];
  weights[currentScene] = 1 - handoff;
  weights[(currentScene + 1) % sceneCount] = handoff;
  const intake = weights[0], recovery = weights[1], reform = weights[2];
  const ink = '#294F46';
  const materialColors = ['#CFC28F', '#A4C3AF', '#B9CFBB'];

  ctx.save(); ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.setLineDash([]); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  M.paintBackground(ctx, width, height, ['#F1EEE1', '#E2E9DB', '#BED5C7'], 'rgba(112,145,120,0.040)');
  ctx.translate(width / 2, height / 2 + minSide * 0.018);
  ctx.scale(minSide / 1080, minSide / 1080);

  // Intake objects share straight, separated corridors and rigid silhouettes.
  // The hood is drawn over their lower endpoint as a physical occluder.
  for (let lane = 0; lane < 3; lane++) {
    const x = (lane - 1) * 100;
    const q = M.fract(loopT / 2.5 + lane / 3);
    const y = M.mix(-412, -302, q);
    const visible = M.ramp(0, 0.12, q) * (1 - M.ramp(0.94, 1, q));
    ctx.save(); ctx.globalAlpha = visible * intake;
    M.fragment(ctx, x, y, lane, 0.92, materialColors[lane], ink);
    ctx.restore();
  }

  // Fixed feet, housing and lid: one compact front-facing machine icon.
  M.box(ctx, -278, 330, 110, 38, 9, '#8FAD99', ink, 4.5);
  M.box(ctx, 168, 330, 110, 38, 9, '#8FAD99', ink, 4.5);
  const caseFill = ctx.createLinearGradient(-344, -292, 344, 344);
  caseFill.addColorStop(0, '#DCE5CD'); caseFill.addColorStop(1, '#B4CCB7');
  M.box(ctx, -344, -292, 688, 636, 29, caseFill, ink, 5.5);
  M.line(ctx, [[-319, -201], [319, -201]], '#92B09E', 2.5);
  M.line(ctx, [[-319, 152], [319, 152]], '#92B09E', 2.5);

  // The entire top opening is one inset slot, with three unobstructed mouths.
  M.box(ctx, -190, -325, 380, 45, 12, '#AEC6AC', ink, 4.5);
  M.box(ctx, -164, -316, 328, 20, 7, '#355E50', ink, 2.5);
  for (const x of [-100, 0, 100]) {
    M.line(ctx, [[x - 23, -306], [x + 23, -306]], '#6E9680', 3);
  }

  M.circle(ctx, -275, -246, 29, '#E1E6CA', ink, 3.2);
  M.circularArrows(ctx, -275, -246, 18, phase, '#527D62');
  M.box(ctx, -220, -258, 90, 11, 5, '#95B29B', null);
  M.box(ctx, -220, -237, 57, 7, 3, '#AAC3AA', null);
  // Three non-textual scene indicators never change their physical bounds.
  for (let i = 0; i < 3; i++) {
    M.box(ctx, 157 + i * 42, -258, 29, 25, 7, M.color('#A1BDA7', '#D6CB92', weights[i]), ink, 2.5);
  }

  // Viewing window with fixed gutters between three independent process lanes.
  M.box(ctx, -289, -181, 578, 318, 18, '#375F50', ink, 4.5);
  const laneCenters = [-180, 0, 180];
  for (let lane = 0; lane < 3; lane++) {
    const center = laneCenters[lane];
    M.box(ctx, center - 76, -153, 152, 237, 11, '#D3DEC5', '#658871', 2.5);
    M.box(ctx, center - 43, -164, 86, 16, 5, '#9CB79C', ink, 2.5);

    ctx.save(); M.rounded(ctx, center - 71, -146, 142, 104, 8); ctx.clip();
    const q = M.fract(loopT / 2.5 + lane / 3);
    const y = M.mix(-171, -32, q);
    const visible = M.ramp(0, 0.06, q) * (1 - M.ramp(0.94, 1, q));
    ctx.globalAlpha = visible * (0.24 + intake * 0.76);
    M.fragment(ctx, center, y, lane, 1.05, materialColors[lane], ink);
    ctx.restore();

    // Opaque processing module cleanly masks the material handoff.
    M.box(ctx, center - 66, -48, 132, 27, 7, '#719B7E', ink, 3);
    for (let j = 0; j < 4; j++) {
      M.line(ctx, [[center - 47 + j * 30, -40], [center - 47 + j * 30, -29]], '#D8E0BD', 3);
    }

    // Pellets retain their size and a 19-unit grid spacing along every lane.
    ctx.save(); M.rounded(ctx, center - 64, -10, 128, 81, 7); ctx.clip();
    for (let row = 0; row < 4; row++) {
      const qPellet = M.fract(loopT / 2.5 + row / 4 + lane * 0.08);
      const yPellet = M.mix(-24, 88, qPellet);
      const alpha = (0.14 + recovery * 0.86) * M.ramp(0, 0.07, qPellet) * (1 - M.ramp(0.93, 1, qPellet));
      ctx.save(); ctx.globalAlpha = alpha;
      for (let col = 0; col < 3; col++) {
        M.box(ctx, center - 25 + col * 19, yPellet - 4.5, 12, 9, 3, materialColors[lane], '#62846A', 1.7);
      }
      ctx.restore();
    }
    ctx.restore();
    M.box(ctx, center - 58, 77, 116, 12, 4, '#84A48C', ink, 2.4);
    M.roller(ctx, center - 38, 109, 10, phase * 10, ink);
    M.roller(ctx, center, 109, 10, phase * 10, ink);
    M.roller(ctx, center + 38, 109, 10, phase * 10, ink);
  }

  // Dedicated output bay. The sheet conveyor never intersects sorting lanes.
  M.box(ctx, -274, 178, 548, 131, 16, '#8AAE95', ink, 4.2);
  M.box(ctx, -222, 196, 444, 90, 10, '#3C6351', ink, 3.2);
  M.roller(ctx, -248, 242, 12, phase * 8, ink);
  M.roller(ctx, 248, 242, 12, phase * 8, ink);
  ctx.save(); M.rounded(ctx, -218, 201, 436, 80, 7); ctx.clip();
  M.line(ctx, [[-220, 265], [220, 265]], '#6D9175', 4);
  for (let item = 0; item < 2; item++) {
    const p = M.fract(loopT / 12.5 + item / 2);
    const x = -780 + 1200 * p;
    ctx.save(); ctx.globalAlpha = 0.22 + reform * 0.78;
    M.box(ctx, x, 214, 314, 43, 5, '#C6D2A8', ink, 2.7);
    M.line(ctx, [[x + 12, 226], [x + 302, 226]], '#E3E5BC', 2.4);
    for (let mark = 0; mark < 8; mark++) {
      M.line(ctx, [[x + 18 + mark * 38, 239], [x + 40 + mark * 38, 239]], '#A2BA8F', 2);
    }
    ctx.restore();
  }
  ctx.restore();

  // Slots and screws share the same baseline and clear the moving window.
  for (let i = 0; i < 5; i++) {
    M.line(ctx, [[-86 + i * 43, 325], [-62 + i * 43, 325]], '#6F957B', 3.4);
  }
  for (const x of [-323, 323]) for (const y of [-272, 323]) M.screw(ctx, x, y, ink, '#CADAC1');
  ctx.restore();
}

// Optional render-host hints. The encoder must enforce the video bitrate.
draw.duration = 25;
draw.sceneCount = 3;
draw.fps = 60;
draw.width = 3840;
draw.height = 2160;
draw.bitrate = 100000000;
